    "Premium：無限下載": "프리미엄: 무제한 다운로드", "👑 隊長（小隊建立者）才能開始記錄；全員在記錄頁按「✋ 準備」後，隊長按開始即全隊一起記錄。": "😘 리더(팀 창작자)만이 시작할 수 있습니다. 모두가 녹음 탭에서 “준비”를 탭하면 리더의 시작이 팀 전체를 위한 녹음을 시작합니다.", "👑 隊長結束了小隊記錄，一起看結算": "😘 리더가 팀 하이킹을 마쳤습니다. 요약은 다음과 같습니다.",
