    "體力普通的一般人": "Toute personne ayant une forme physique moyenne", "有健行經驗、體力較佳者": "Randonneurs expérimentés et en bonne forme physique", "齊全登山裝備、禦寒衣物": "Équipement d'alpinisme complet et couches chaudes",
    "過夜裝備、足夠飲水食物": "Équipement de nuit, beaucoup de nourriture et d'eau", "路面平整、坡度平緩，連娃娃車和輪椅都能通行。": "Sentiers plats et doux – adaptés aux poussettes et aux fauteuils roulants.", "交通方便、路面好走、設施完善，半天到一天就能輕鬆走完。": "Accès facile, bonne surface, installations complètes — réalisé en une demi-journée ou une journée.",
