    "坡度稍陡或有少數比較難走的路段，但設施完善、路面平整，一天內可完成。": "坡度稍陡或有少数比较难走的路段，但设施完善、路面平整，一天内可完成。", "路面平整、坡度平緩，連娃娃車和輪椅都能通行。": "路面平整、坡度平缓，连娃娃车和轮椅都能通行。", "偏遠高山（約 3,000 公尺以上），路況不佳、危險路段多，需三天以上，建議專業人員帶領。": "偏远高山（约 3,000 公尺以上），路况不佳、危险路段多，需三天以上，建议专业人员带领。",
