    "最低": "最低", "全台 2100+ 條步道一手掌握。搜尋、分級、記錄、養成，一起走進山林。": "全台 2100+ 条步道一手掌握。搜寻、分级、记录、养成，一起走进山林。", "🌤 最適合出發：": "🌤 最适合出发：",
    "搜尋步道看官方難度分級、真實路線與海拔剖面；還有天氣、周邊人文景點與美食。用『精選主題輯』快速找古道、瀑布、親子路線。": "搜寻步道看官方难度分级、真实路线与海拔剖面；还有天气、周边人文景点与美食。用『精选主题辑』快速找古道、瀑布、亲子路线。", "小隊同行・我是隊長": "小队同行・我是队长", "出發前可預載離線地圖，山區沒訊號也看得到；收藏步道、行程可一鍵備份，換手機不怕遺失。": "出发前可预载离线地图，山区没讯号也看得到；收藏步道、行程可一键备份，换手机不怕遗失。",
    "走路就能養寵物！從一顆蛋開始，靠里程進化：🥚→🦊→🐅→🐉。撿果實、每天餵食、提升親密度，走越多牠陪你長越快。": "走路就能养宠物！从一颗蛋开始，靠里程进化：🥚→🦊→🐅→🐉。捡果实、每天喂食、提升亲密度，走越多它陪你长越快。", "邊走邊記里程、步數、卡路里、爬升與即時海拔曲線；自動暫停、中斷可復原，離線也能用。": "边走边记里程、步数、卡路里、爬升与即时海拔曲线；自动暂停、中断可复原，离线也能用。", "小隊同行": "小队同行",
    "是另一個獨立標記（不是難度等級）：代表這條步道": "是另一个独立标记（不是难度等级）：代表这条步道", "模擬：沿此步道路線前進": "模拟：沿此步道路线前进", "資料來源：OpenStreetMap 貢獻者（社群步道，詳細資料有限": "资料来源：OpenStreetMap 贡献者（社群步道，详细资料有限",
    "記錄中・在路線上": "记录中・在路线上", "準備": "准备", "分級數字越大代表越難走。等級依": "分级数字越大代表越难走。等级依",
    "一階階進化 —— 走路的里程、餵食、每日任務與好友送的果實，都會讓牠成長。": "一阶阶进化 —— 走路的里程、喂食、每日任务与好友送的果实，都会让它成长。", "林業及自然保育署「自然步道使用困難度分級標準」": "林业及自然保育署「自然步道使用困难度分级标准」", "美食功能尚未設定（需在 Render 設定 GOOGLE_PLACES_KEY": "美食功能尚未设定（需在 Render 设定 GOOGLE_PLACES_KEY",
