// 全域翻譯（翻譯年糕共用）：Google 免金鑰端點優先，失敗退 MyMemory。
// 兩層快取：同段文字只翻一次（記憶體 + localStorage 各存 120 筆，免費 API 有每日額度）
const _trMem = new Map();
